    ],
    "source_section_id": null
  }
],
"semantic_rules": [
  {
    "id": "G186:3.1:rule01",
    "kind": "source-semantic-rule",
    "statement_zh": "实施期间的治理既指导变革与预期价值对齐，也控制其保持在相应路径上。",
    "boundary_zh": "目标必须经过批准，指导与控制不是架构师个人偏好。",
    "evidence": [
      {
        "source_unit_id": "G186:p0025:c011",
        "pdf_page": 25,
        "source_block_ids": [
          "G186:p0025:b023",
          "G186:p0025:b024",
          "G186:p0025:b025",
          "G186:p0025:b026",
          "G186:p0025:b027",
          "G186:p0025:b028"
        ],
        "quote_en": "Guidance on effective change will take place during the activity to realize the approved EA. During implementation,[1] EA is used by the stakeholders to govern change. The first part of governance is to direct change activity – align the change with the optimal path to realizing the expected value. The second part of governance is to control the change activity – ensuring the change stays on the optimal path.",
        "source_path": "togaf-standard-10th/G186e.pdf",
        "source_sha256": "ed1c26faba5023a8d1b32b0ec893d75a3bb1d7a6508e99fa56ded079585d922a"
      }
    ]
  },
  {
    "id": "G186:3.1:rule02",
    "kind": "source-semantic-rule",
    "statement_zh": "当前状态与未来状态的差距必须能够说明要改变什么及其影响。",
    "boundary_zh": "项目对齐检查还需优先级与完整目标集合，不能仅比较技术组件。",
    "evidence": [
      {
        "source_unit_id": "G186:p0026:c000",
        "pdf_page": 26,
        "source_block_ids": [
          "G186:p0026:b001",
          "G186:p0026:b002",
          "G186:p0026:b003",
          "G186:p0026:b004",
          "G186:p0026:b005",
          "G186:p0026:b006",
          "G186:p0026:b007",
          "G186:p0026:b008"
        ],
        "quote_en": "In its simplest terms, EA must describe the future state and the current state of the Enterprise. The description of the future state enables the right people to understand what must be done to meet the Enterprise’s goals, objective, mission, and vision in the context within which the Enterprise operates. The gap between the Enterprise’s current state and future state highlights what must change. A good EA facilitates effective governance, management, risk management, and exploitation opportunities. A list of gaps makes obvious what must change and the implications of that change: is the proposed project in alignment with what is needed? In alignment with priority? In alignment with the complete set of goals and objectives?",
        "source_path": "togaf-standard-10th/G186e.pdf",
        "source_sha256": "ed1c26faba5023a8d1b32b0ec893d75a3bb1d7a6508e99fa56ded079585d922a"
      }
    ]
  }
],
