        "source_block_ids": [
          "G186:p0036:b033",
          "G186:p0036:b034",
          "G186:p0036:b035",
          "G186:p0036:b036"
        ],
        "quote_en": "Viewpoints are specialized communication to stakeholders that explicitly address a concern. Keep in mind that any associated requirements may not be satisfied by the architecture. The view is not a demonstration that the stakeholder should be happy; rather it is a demonstration of how the architecture addresses the concern.",
        "source_path": "togaf-standard-10th/G186e.pdf",
        "source_sha256": "ed1c26faba5023a8d1b32b0ec893d75a3bb1d7a6508e99fa56ded079585d922a"
