    "id": "G186:5.1.1:rule03",
    "kind": "source-semantic-rule",
    "statement_zh": "支持文档必须自标状态和时间线，使相关性、有效性与时效性可判定。",
    "boundary_zh": "旧的已实现架构仍可能有用，不能以最近修改时间替代有效期。",
    "evidence": [
      {
        "source_unit_id": "G186:p0052:c003",
        "pdf_page": 52,
        "source_block_ids": [
          "G186:p0052:b010",
          "G186:p0052:b011",
          "G186:p0052:b012",
          "G186:p0052:b013",
          "G186:p0052:b014",
          "G186:p0052:b015"
        ],
        "quote_en": "Supporting documents maintained must clearly identify their state. Without this ability, the Practitioner is pragmatically uncertain whether the document they are looking at is relevant, valid, or useful. They must readily allow the Practitioner to determine their recency. In practice, a candidate or target, or distantly realized current state architecture might be useful to the Practitioner. Usefulness is predicated on the “self-identification” of state and timeline. Without such markers, each supporting document is nothing but noise.",
        "source_path": "togaf-standard-10th/G186e.pdf",
        "source_sha256": "ed1c26faba5023a8d1b32b0ec893d75a3bb1d7a6508e99fa56ded079585d922a"
      }
    ]
  }
