  "source_section_id": "G186:s0078",
  "section_number": "7.4.1",
  "title_en": "7.4.1. Confirm Enterprise Change Attributes",
  "title_zh": "7.4.1 确认企业变革属性",
  "status": "source-compared-revised",
  "translation_mode": "revised-existing-translation",
  "pdf_pages": [
