"semantic_rules": [
  {
    "id": "G186:12.3:rule01",
    "kind": "source-semantic-rule",
    "statement_zh": "事件导致风险偏好改变时是需求变化，架构需调整目标及达成目标的工作建议。",
    "boundary_zh": "如没有成本可接受的选项，取消目标或取消变更也可能进入利益相关者选择。",
    "evidence": [
      {
        "source_unit_id": "G186:p0127:c002",
        "pdf_page": 127,
        "source_block_ids": [
          "G186:p0127:b006",
          "G186:p0127:b007",
          "G186:p0127:b008",
          "G186:p0127:b009",
          "G186:p0127:b010",
          "G186:p0127:b011"
        ],
        "quote_en": "An incident changes the stakeholders’ preferences with regard to risk. This is a change in requirement, and the architecture must adjust. The central role of the Practitioner is to provide solid advice on what changes to the target, and the associated work to achieve the change will reach an acceptable certainty of reaching the stakeholders’ objective. Practitioners should not be surprised when there are few changes that have an acceptable cost, and the stakeholder is faced with the option of canceling the objective or canceling the change.",
        "source_path": "togaf-standard-10th/G186e.pdf",
        "source_sha256": "ed1c26faba5023a8d1b32b0ec893d75a3bb1d7a6508e99fa56ded079585d922a"
      }
    ]
  },
  {
    "id": "G186:12.3:rule02",
    "kind": "source-semantic-rule",
    "statement_zh": "风险偏好表达为达成成果愿承担风险的界线，风险容忍度处理偏离预期。",
    "boundary_zh": "这是本指南的表述；示例金额和零损失容忍并非当前企业授权。",
    "evidence": [
      {
        "source_unit_id": "G186:p0126:c012",
        "pdf_page": 126,
        "source_block_ids": [
          "G186:p0126:b030",
          "G186:p0126:b031",
          "G186:p0126:b032",
          "G186:p0126:b033",
          "G186:p0126:b034"
        ],
        "quote_en": "The risk appetite provides guidance balancing the amount of risk taken to achieve an expected outcome. Risk appetite is typically expressed as a boundary on a risk/business impact and likelihood grid, or qualitative measures. For example, the Enterprise will risk $x for $y reward this year, or has zero tolerance for loss of life. A well understood risk appetite defines both the level of risk the organization is willing to accept as well as its strategy in defining this level.",
        "source_path": "togaf-standard-10th/G186e.pdf",
        "source_sha256": "ed1c26faba5023a8d1b32b0ec893d75a3bb1d7a6508e99fa56ded079585d922a"
      }
    ]
  }
],
