      "preferred_zh": "汇集式/协作式/集中式",
      "distinction_zh": "主控与同步风格，可组合且需范围定义。"
    },
    {
      "term_en": "Plateau",
      "preferred_zh": "高原（稳定架构状态）",
      "distinction_zh": "有限时间相对稳定状态，不是技术平台。"
    },
    {
      "term_en": "PoA/PoC",
      "preferred_zh": "采集点/消费点",
      "distinction_zh": "数据交换的作用位置，不必是独立物理系统。"
    },
    {
      "term_en": "Current/Historical Value",
      "preferred_zh": "当前值/历史值",
      "distinction_zh": "当前权威值不能覆盖既往交易计算依据。"
    },
    {
      "term_en": "Qualification",
      "preferred_zh": "画像评估/适用性评估",
      "distinction_zh": "就质量、数量、频率、价值等特征评估，不是认证。"
    }
  ],
