  "terminology_zh": [
    {
      "term_en": "Customer/Party",
      "preferred_zh": "客户/一方（主体）",
      "distinction_zh": "客户是主体扮演的角色，主体可为自然人或组织。"
    },
    {
      "term_en": "Kernel Customer Data",
      "preferred_zh": "内核客户数据",
      "distinction_zh": "跨部门共享客户基础信息，范围按业务定义。"
    },
    {
      "term_en": "Mastership",
      "preferred_zh": "主控权",
      "distinction_zh": "谁维护权威值，区别于副本存储、可见性和信息所有权。"
    },
    {
      "term_en": "Golden Record/System of Record",
      "preferred_zh": "黄金记录/记录系统",
      "distinction_zh": "受信数据结构与承载主数据的信息系统，不能互换为产品名。"
    },
    {
      "term_en": "Customer Data Owner/Data Steward/Data Manager",
      "preferred_zh": "客户数据所有者/数据管家/数据经理",
      "distinction_zh": "问责、管护执行和管理职责不同，具体授权需确认。"
    },
    {
      "term_en": "Match/Merge/Unmerge",
      "preferred_zh": "匹配/合并/取消合并",
      "distinction_zh": "候选判断、记录变更和恢复是不同动作。"
    },
    {
      "term_en": "Consolidation/Cooperation/Centralized",
      "preferred_zh": "汇集式/协作式/集中式",
      "distinction_zh": "主控与同步风格，可组合且需范围定义。"
    },
    {
      "term_en": "Plateau",
      "preferred_zh": "高原（稳定架构状态）",
      "distinction_zh": "有限时间相对稳定状态，不是技术平台。"
    },
    {
      "term_en": "PoA/PoC",
      "preferred_zh": "采集点/消费点",
      "distinction_zh": "数据交换的作用位置，不必是独立物理系统。"
    },
    {
      "term_en": "Current/Historical Value",
      "preferred_zh": "当前值/历史值",
      "distinction_zh": "当前权威值不能覆盖既往交易计算依据。"
    },
    {
      "term_en": "Qualification",
      "preferred_zh": "画像评估/适用性评估",
      "distinction_zh": "就质量、数量、频率、价值等特征评估，不是认证。"
    }
