    {
      "id": "G21H:4.3.2:rule03",
      "kind": "source-semantic-rule",
      "statement_zh": "公司治理规定可接受行为及偏差处理，EA 战略说明愿景、原则和需求。",
      "boundary_zh": "架构师的生成建议不是公司已采纳的治理授权。",
      "evidence": [
        {
          "source_unit_id": "G21H:p0031:c007",
          "pdf_page": 31,
          "source_block_ids": [
            "G21H:p0031:b023",
            "G21H:p0031:b024",
            "G21H:p0031:b025",
            "G21H:p0031:b026",
            "G21H:p0031:b027",
            "G21H:p0031:b028",
            "G21H:p0031:b029",
            "G21H:p0031:b030",
            "G21H:p0031:b031",
            "G21H:p0031:b032"
          ],
          "quote_en": "The overarching framework that sets the tone for the culture of the enterprise. The corporate governance framework for the enterprise ultimately determines the nature of behaviors that are acceptable within the enterprise and how deviation from such behaviors is handled to ensure that the enterprise stays on course for what it is intended to achieve. It will influence the nature of policy framework and the overall Business Operating Environment of the enterprise, to ensure that there are appropriate management and governance controls in place to enable the enterprise to optimize its investment and benefits and generate sustainable value within acceptable level of costs and risks as a good corporate citizen. The Enterprise Architecture strategy sets the tone for the appropriate strategic investment as it outlines the Architecture Vision, Architecture Principles, and requirements to realize the intended business direction.",
          "source_path": "togaf-standard-10th/G21He.pdf",
          "source_sha256": "40881f73b66ae8cfabc279aba8fe3767182ac3e865823054d0aca58f6292a470"
        }
      ]
    }
