  "terminology_zh": [
    {
      "term_en": "Metadata",
      "preferred_zh": "元数据",
      "distinction_zh": "描述数据内容、语境、来源、质量、治理及使用的附加信息。"
    },
    {
      "term_en": "Metadata Management",
      "preferred_zh": "元数据管理",
      "distinction_zh": "规划、实施与控制高质量、集成元数据可访问性的活动。"
    },
    {
      "term_en": "Business/Technical/Operational Metadata",
      "preferred_zh": "业务/技术/运营元数据",
      "distinction_zh": "分析类别，可交叉并需分别保留来源和治理。"
    },
    {
      "term_en": "Business Glossary/Data Dictionary",
      "preferred_zh": "业务术语表/数据字典",
      "distinction_zh": "业务概念与物理数据表示的不同制品。"
    },
    {
      "term_en": "Normative/Collaborative",
      "preferred_zh": "规范式/协作式",
      "distinction_zh": "质量保障方式选择，不是成熟度等级。"
    },
    {
      "term_en": "Consolidation/Hybrid/Unified",
      "preferred_zh": "汇集式/混合式/统一式",
      "distinction_zh": "元数据主副本、流程和用户体验集成模型，不是供应商名称。"
    },
    {
      "term_en": "Manual/Push/Pull",
      "preferred_zh": "手工摄取/推送/拉取",
      "distinction_zh": "交换方式，权限、人工责任和安全边界不同。"
    },
    {
      "term_en": "Metadata Inference",
      "preferred_zh": "元数据推断",
      "distinction_zh": "自动发现候选结构/关系，需人工、质量和安全复核。"
    },
    {
      "term_en": "Business Rule/Technical Rule",
      "preferred_zh": "业务规则/技术规则",
      "distinction_zh": "业务治理定义与物理可执行组件，执行结果另行记录。"
    },
    {
      "term_en": "SME",
      "preferred_zh": "源文为Small and Medium Enterprise(s)",
      "distinction_zh": "正文采集语境可能意指Subject Matter Expert，但当前记录保留源文并标为歧义。"
    },
    {
      "term_en": "DPIA",
      "preferred_zh": "Data Privacy/Protection Impact Assessment",
      "distinction_zh": "不同源单元用词需分别追踪，不能无证据统一展开。"
    }
