      "term_en": "BI & Analytics Capability",
      "preferred_zh": "商业智能与分析能力",
      "distinction_zh": "人员/流程/组织/系统共同实现，不等于平台。"
    },
    {
      "term_en": "Transition Architecture",
      "preferred_zh": "过渡架构",
      "distinction_zh": "有限时间可运营的相对稳定状态，不等于所有四步。"
    },
    {
      "term_en": "Single Point of Truth",
      "preferred_zh": "单一事实来源",
      "distinction_zh": "需记录历史数据范围及权威语义，不等同所有主数据归一个物理库。"
    },
    {
      "term_en": "Business Function/Application Function",
      "preferred_zh": "业务功能/应用功能",
      "distinction_zh": "业务行为聚合与自动化行为，不直接对应产品和岗位。"
    },
    {
      "term_en": "Raw/Prepared/Information Data",
      "preferred_zh": "原始/已准备/信息数据",
      "distinction_zh": "未变更来源、通用技术准备、特定业务加工三种语义。"
    },
    {
      "term_en": "Qualification",
      "preferred_zh": "适用性评估",
      "distinction_zh": "来源和数据是否适合用途，不是第三方认证。"
    },
    {
      "term_en": "Next Best Customer Action",
      "preferred_zh": "面向客户的下一最佳行动",
      "distinction_zh": "next修饰action。"
    },
    {
      "term_en": "Model Exploration/Validation/Deployment",
      "preferred_zh": "模型探索/验证/部署",
      "distinction_zh": "不同阶段和证据状态，线上准确性需继续观测。"
    },
    {
      "term_en": "Data Democratization",
      "preferred_zh": "数据民主化",
      "distinction_zh": "按工作需要共享语义和数据，同时受保密与访问权控制。"
    },
    {
      "term_en": "Architecture Requirement",
      "preferred_zh": "架构需求",
      "distinction_zh": "影响架构决策的需要，非工具名或详细测试规格。"
    }
  ],
